p=Page('156-4',37)
for a,b in [(r'\unsure{ion}',r'\unsure{ion|.}'),(r'\unsure{\relbar\joinrel\relbar\!\shortmid|\longrightarrow}',r'\relbar\joinrel\relbar\!\shortmid'),(r'\unsure{\mathrm P|\mathcal P}',r'\mathcal P'),(r'\unsure{L|\mathcal L}',r'\mathcal L'),(r'\unsure{admissible|admissibles}','admissible'),(r'\unsure{a)}','a)'),(r'\unsure{\circ|0}',r'\circ'),(r'\unsure{$X$}',r'$X$'),(r'\unsure{frontière}',r'\unsure{frontière|fr.}'),(r'\inserted{\uline{bord d\'ombre}}',r'\inserted{\uuline{bord d\'ombre}}'),(r'\unsure{\longrightarrow|\relbar\joinrel\relbar}',r'\longrightarrow'),(r'\mathrm P(L)',r'\mathcal P(L)'),(r'\unsure{les}','les'),(r'\unsure{Soit}','Soit'),(r'\unsure{,|.}',','),(r'\unsure{équiv.}','équiv.'),(r'\unsure{\subseteq|\subset}',r'\unsure{\subseteq|\subset|\in}')]:
 if a not in p.text and 'bord' in a:continue
 p.replace(a,b)
p.replace("\\inserted{\\uline{bord d'ombre}}","\\inserted{\\uuline{bord d'ombre}}")
p.replace(r'} appelle $\widetilde X^\circ$',r'} \inserted{appelle} $\widetilde X^\circ$')
p.replace(r'\widetilde X^\circ\subseteq\widetilde Y',r'\widetilde X^\circ\unsure{\subseteq|\subset|\in}\widetilde Y')
p.text=re.sub(r'(?<![A-Za-z\\])L(?![A-Za-z])',r'\\mathcal L',p.text)
p.text=p.text.replace(r'\mathcal \mathcal L',r'\mathcal L')
