c('condition iii relation','subseteq','subset','[subseteq|subset|in]','The open curved sign has a heavy low return and a partly merged inner horizontal stroke; exact sign remains uncertain.','four',True,kind='misread symbol or index',conf='low',con='Marks the retraced relation in condition iii as unresolved rather than choosing a mathematical inclusion from context.')
for loc,rd,why,cr,cf in [('cancelled opening ending','ion|.','Terminal strokes merge with strike.','top','low'),('first figure alphabet',r'F|\mathcal F','Looped lower return unlike some neighboring F forms.','top','medium'),('boundary erased letter','X|Y','Crossed original arms.','boundary','low'),('marginal heading','Déf','Initial letter densely overwritten; cancellation state insecure.','margin','low'),('old boundary noun','frontière|fr.','Overlapping rules obscure ending.','name','low'),('second map left connector',r'\longmapsto|\mapstochar\relbar\joinrel\relbar','Right endpoint thickened.','map2','medium'),('condition ii sign',r'\subseteq|\subset|\in','Retraced bowl and bars merge.','four','low'),('condition iii label','iii','Joined numeral loops.','four','low'),('condition iii sign',r'\subseteq|\subset|\in','Heavy inner/lower traces.','four','low')]:p.doubt(loc,rd,why,cr,cf)
